package org.springframework.samples.petclinic.rest.function.owner;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.Locale;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;

/**
 * Assigns the owner's deterministic {@code householdId}: the first 12 (upper-case) hex characters of
 * the SHA-256 of {@code normalizedLastName + '|' + postcode}. The id is derived purely from the
 * (lastName, postcode) pair, so every owner with the same lastName and postcode receives the same
 * value automatically, regardless of creation order and without any repository lookup or opt-in.
 *
 * <p>Because the household is now keyed on (lastName, postcode), owners sharing that pair are the
 * same household. This computed id is the single source of truth the household consumers key off:
 * {@link CheckOwnerIdentityUnique} (the household-duplicate 409 block),
 * {@link DetectOwnerPossibleDuplicate} and {@link DeriveOwnerHouseholdSize}. The request's
 * {@code sharesHousehold} flag no longer creates the link — the link is implicit in the shared id —
 * it only bypasses the duplicate block (see {@link CheckOwnerIdentityUnique}).
 *
 * <p>Runs after {@link BuildOwner} has created the entity and before {@link CheckOwnerIdentityUnique}
 * (which sees the resolved {@code householdId}) and {@link SaveOwner} persists it.
 */
public class AssignOwnerHousehold {

    public void service(@Val Owner owner) {
        owner.setHouseholdId(householdId(owner.getLastName(), owner.getPostcode()));
    }

    /**
     * The single source of truth for an owner's household identity: the first 12 upper-case hex
     * characters of the SHA-256 of {@code normalize(lastName) + '|' + postcode}. An absent postcode
     * contributes an empty segment. Two owners share a household exactly when this value is equal.
     */
    static String householdId(String lastName, String postcode) {
        String input = normalize(lastName) + "|" + (postcode == null ? "" : postcode);
        try {
            byte[] digest = MessageDigest.getInstance("SHA-256")
                    .digest(input.getBytes(StandardCharsets.UTF_8));
            StringBuilder sb = new StringBuilder(12);
            for (int i = 0; i < 6; i++) {
                sb.append(String.format("%02x", digest[i]));
            }
            return sb.toString().toUpperCase(Locale.ROOT);
        }
        catch (NoSuchAlgorithmException ex) {
            throw new IllegalStateException("SHA-256 not available", ex);
        }
    }

    /** Lower-cased, trimmed, with internal whitespace runs collapsed to a single space. */
    static String normalize(String value) {
        if (value == null) {
            return "";
        }
        return value.trim().replaceAll("\\s+", " ").toLowerCase();
    }
}

package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;

/**
 * Flags the new owner as a possible (soft) duplicate, keyed off the computed
 * {@link Owner#getHouseholdId() householdId}: an owner is a possible duplicate when an earlier owner
 * shares its household (same lastName and postcode).
 *
 * <p>A <em>declared</em> household member — one created with {@code sharesHousehold} true — is never
 * flagged: it deliberately joins the household, so it is not a suspected duplicate. Any other owner
 * sharing an existing household has already been rejected 409 by {@link CheckOwnerIdentityUnique},
 * so in practice this leaves {@code possibleDuplicate} false; keeping the check here keys the soft
 * signal off the same household id as the hard block.
 *
 * <p>Runs after {@link BuildOwner}/{@link AssignOwnerHousehold} and before {@link SaveOwner},
 * scanning only pre-existing (already persisted) owners — the new owner has no id yet and is skipped.
 * The earliest such match (lowest id) is recorded: {@code possibleDuplicate} is set true and
 * {@code possibleDuplicateOf} to that owner's id; otherwise {@code possibleDuplicate} is false and
 * {@code possibleDuplicateOf} is left null. Both are stored on the built owner so the saved and
 * returned record carries them.
 */
public class DetectOwnerPossibleDuplicate {

    public void service(@Val OwnerFieldsDto request, @Val Owner owner, OwnerRepository ownerRepository) {
        Owner match = null;
        if (!Boolean.TRUE.equals(request.getSharesHousehold())) {
            String householdId = owner.getHouseholdId();
            if (householdId != null) {
                for (Owner existing : ownerRepository.findAll()) {
                    if (existing.getId() == null
                            || existing.getId().equals(owner.getId())) {
                        continue;
                    }
                    if (householdId.equals(existing.getHouseholdId())) {
                        if (match == null || existing.getId() < match.getId()) {
                            match = existing;
                        }
                    }
                }
            }
        }
        if (match != null) {
            owner.setPossibleDuplicate(true);
            owner.setPossibleDuplicateOf(match.getId());
        }
        else {
            owner.setPossibleDuplicate(false);
            owner.setPossibleDuplicateOf(null);
        }
    }
}

