        if (this.namesakeCount != null && this.namesakeCount == 0) {
            level++;
        }
        return Math.min(level, 3);
    }

    /** Fixed city-to-region table used to derive {@link #getLocality()}. */
    private static final Map<String, String> CITY_REGION = Map.of(
        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");

    /** Region -> inclusive 4-digit postcode range {low, high} used to derive {@link #getLocality()}. */
    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
        "NSW", new int[] {2000, 2099}, "VIC", new int[] {3000, 3099}, "QLD", new int[] {4000, 4099});

    /**
     * The fixed city-to-region mapping ({@code Sydney -> NSW}, {@code Melbourne -> VIC},
     * {@code Brisbane -> QLD}): the region for {@code city}, or {@code null} when the city is not in
     * the table. Used only by postcode validation, which branches on "known region or not" by testing
     * for {@code null} before range-checking the postcode.
     */
    public static String regionOf(String city) {
        return CITY_REGION.get(city);
    }

    /**
     * The region whose fixed postcode range ({@code NSW 2000-2099}, {@code VIC 3000-3099},
     * {@code QLD 4000-4099}) contains {@code postcode}, or {@code null} when {@code postcode} is
     * absent, not a 4-digit number, or in no known range.
     */
    public static String regionOfPostcode(String postcode) {
        if (postcode == null || postcode.isEmpty()) {
            return null;
        }
        int value;
        try {
            value = Integer.parseInt(postcode);
        } catch (NumberFormatException ex) {
            return null;
        }
        for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
            int[] range = entry.getValue();
            if (value >= range[0] && value <= range[1]) {
                return entry.getKey();
            }
        }
        return null;
    }

    /**
     * The owner's region, derived at response time from the {@code REGION} prefix of the
     * {@link #customerCode} (the segment before the first {@code '-'}). Because the customer code is
     * assigned as {@code <REGION>-<HASH8>} with REGION taken from the postcode, the locality follows
     * the same region-and-hash identity as the customer code. {@code UNKNOWN} when the owner has no
     * customer code.
     */
    public String getLocality() {
        if (this.customerCode == null) {
            return "UNKNOWN";
        }
        int dash = this.customerCode.indexOf('-');
        return dash < 0 ? this.customerCode : this.customerCode.substring(0, dash);
    }

    /**
     * The owner's preferred contact channel, derived at response time: {@code EMAIL} when an
     * email is present, otherwise {@code PHONE}. Not persisted.
     */
    public String getContactPreference() {
        return (this.email != null && !this.email.isEmpty()) ? "EMAIL" : "PHONE";
    }

    /**
     * A single Luhn check digit (0-9) derived at response time over the digits contained in
     * {@link #customerCode} (non-digit characters are ignored), or {@code null} when the owner
     * has no customer code. Computed with the standard Luhn algorithm — doubling every second
     * digit from the right, subtracting 9 from any result over 9, and taking
     * {@code (10 - sum % 10) % 10}. Not persisted.
     */
    public Integer getCheckDigit() {
        if (this.customerCode == null) {
            return null;
        }
        int sum = 0;
        boolean dbl = true;
        for (int i = this.customerCode.length() - 1; i >= 0; i--) {
            char c = this.customerCode.charAt(i);
            if (c < '0' || c > '9') {
                continue;
            }
            int d = c - '0';
            if (dbl) {
                d *= 2;
                if (d > 9) {
                    d -= 9;
                }
            }
            sum += d;
            dbl = !dbl;
        }
        return (10 - (sum % 10)) % 10;
    }

    /**
     * The single source of truth for an owner's identity: the derived key
     * {@code normalizedTelephone|email|householdId}, joined with '|'. The telephone is stored in
     * canonical E.164 form and the email lower-cased, so this key composes their canonical values;
     * an absent email or householdId contributes an empty segment. Two owners are duplicates exactly
     * when their whole identity keys are equal — differing in any one segment (for example two
     * members of the same household with different telephones) yields different keys. Derived at
     * response time and used by the create pipeline's single duplicate check; not persisted.
     */
    public String getIdentityKey() {
        return keyPart(this.telephone) + "|" + keyPart(this.email) + "|" + keyPart(this.householdId);
    }

    private static String keyPart(String value) {
        return value == null ? "" : value;
    }

    protected Set<Pet> getPetsInternal() {
        if (this.pets == null) {
            this.pets = new HashSet<>();
        }
        return this.pets;
    }

    protected void setPetsInternal(Set<Pet> pets) {
        this.pets = pets;
    }

    public List<Pet> getPets() {
        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
        return Collections.unmodifiableList(sortedPets);
    }

    public void setPets(List<Pet> pets) {
        this.pets = new HashSet<>(pets);
    }

    public void addPet(Pet pet) {
        getPetsInternal().add(pet);
        pet.setOwner(this);
    }

    /**
     * Return the Pet with the given name, or null if none found for this Owner.
     *
     * @param name to test
     * @return true if pet name is already in use
     */
    public Pet getPet(String name) {
        return getPet(name, false);
    }

    /**
     * Return the Pet with the given name, or null if none found for this Owner.
     *
     * @param name to test
     * @return true if pet name is already in use
     */
    public Pet getPet(String name, boolean ignoreNew) {
        name = name.toLowerCase();
        for (Pet pet : getPetsInternal()) {
            if (!ignoreNew || !pet.isNew()) {
                String compName = pet.getName();
                compName = compName.toLowerCase();
                if (compName.equals(name)) {
                    return pet;
                }
            }
        }
        return null;
    }

    public Pet getPet(Integer petId) {
        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
    }

    @Override
    public String toString() {
        return new ToStringCreator(this)

            .append("id", this.getId())
            .append("new", this.isNew())
            .append("lastName", this.getLastName())
            .append("firstName", this.getFirstName())
            .append("address", this.address)
            .append("city", this.city)
            .append("telephone", this.telephone)
            .append("email", this.email)
            .toString();
    }
}

package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.InvalidTelephoneException;

/**
 * Normalizes the owner's telephone on create into E.164 form, mutating the validated request in
 * place so later steps store and return the E.164 value. Spaces, dashes and brackets are stripped.
 * A leading '+' and its country code are kept as given; otherwise country code '+61' is assumed and
 * a single leading '0' is dropped from the national digits (so {@code 0412 345 678} becomes
 * {@code +61412345678}). The result must carry 8 to 15 digits after the '+', and its national
 * number (the digits after the country code) must match the length that country requires — '+61'
 * needs 9 national digits, '+1' needs 10. Anything that cannot form valid E.164 is rejected 400 via
 * {@link InvalidTelephoneException}.
 */
public class NormalizeOwnerTelephone {

    public void service(@Val OwnerFieldsDto request) throws InvalidTelephoneException {
        request.setTelephone(toE164(request.getTelephone()));
    }

    /**
     * The single source of truth for what "same telephone" means: converts a raw telephone into its
     * E.164 form. Spaces, dashes and brackets are removed; a leading '+' and country code are kept,
     * otherwise '+61' is assumed and a single leading '0' is dropped from the national digits. The
     * digits after the '+' must number 8 to 15, no other characters may remain, and the national
     * number must have the length the country code requires ('+61' => 9, '+1' => 10). The E.164 value
     * feeds the derived {@link org.springframework.samples.petclinic.model.Owner#getIdentityKey()
     * identityKey} so the request side and stored owners are normalized identically.
     *
     * @throws InvalidTelephoneException if the value cannot form valid E.164.
     */
    static String toE164(String telephone) throws InvalidTelephoneException {
        if (telephone == null) {
            throw invalid();
        }
        String cleaned = telephone.replaceAll("[\\s\\-()]", "");
        String digits;
        if (cleaned.startsWith("+")) {
            digits = cleaned.substring(1);
        }
        else {
            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
            digits = "61" + national;
        }
        if (!digits.matches("\\d{8,15}")) {
            throw invalid();
        }
        checkNationalLength(digits);
        return "+" + digits;
    }

    /**
     * Rejects a number whose national number (the digits after the country code) does not match the
     * length that country code requires: '+61' => 9 national digits, '+1' => 10. Country codes not
     * listed here are left to the generic 8-to-15 digit rule.
     */
    private static void checkNationalLength(String digits) throws InvalidTelephoneException {
        String countryCode;
        int requiredNationalLength;
        if (digits.startsWith("61")) {
            countryCode = "61";
            requiredNationalLength = 9;
        }
        else if (digits.startsWith("1")) {
            countryCode = "1";
            requiredNationalLength = 10;
        }
        else {
            return;
        }
        int nationalLength = digits.length() - countryCode.length();
        if (nationalLength != requiredNationalLength) {
            throw new InvalidTelephoneException("Telephone with country code '+" + countryCode
                    + "' must have " + requiredNationalLength + " national digits, but had "
                    + nationalLength);
        }
    }

    private static InvalidTelephoneException invalid() {
        return new InvalidTelephoneException(
                "Telephone must form a valid E.164 number with 8 to 15 digits after the '+'");
    }
}

package org.springframework.samples.petclinic.rest.function.owner;

import java.util.Locale;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;

/**
 * Normalizes the owner's optional email so it is stored and returned lower-cased, mutating
 * the validated request in place so later steps persist and return the normalized value.
 * Syntactic validity is enforced declaratively by the {@code @Email} constraint on the
 * request DTO (checked at {@link ValidateOwner}), so a present but invalid address is already
 * rejected 400 before this step runs; a missing (null) email is left untouched.
 */
public class NormalizeOwnerEmail {

    public void service(@Val OwnerFieldsDto request) {
        String email = request.getEmail();
        if (email != null) {
            request.setEmail(normalize(email));
        }
    }

    /**
     * The single source of truth for an email's canonical form: lower-cased. Null-safe so it can
     * canonicalize an existing owner's (possibly absent) stored value. The canonical value feeds the
     * derived {@link org.springframework.samples.petclinic.model.Owner#getIdentityKey() identityKey},
     * so the "same email" definition can never drift from how emails are stored and returned.
     */
    static String normalize(String email) {
        return email == null ? null : email.toLowerCase(Locale.ROOT);
    }
}
